import{_ as s,C as o,o as r,c as l,j as t,a,E as d,ag as c}from"./chunks/framework.HG0H2VLS.js";const w=JSON.parse('{"title":"MediaMeta","description":"","frontmatter":{},"headers":[],"relativePath":"cc-components/media-meta.md","filePath":"cc-components/media-meta.md"}'),m={name:"cc-components/media-meta.md"},h={id:"mediameta",tabindex:"-1"};function p(u,e,g,b,f,y){const i=o("Badge"),n=o("ComponentDemo");return r(),l("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-mediameta",tabindex:"-1"},[a("title: MediaMeta "),t("a",{class:"header-anchor",href:"#title-mediameta","aria-label":'Permalink to "title: MediaMeta"'},"​")],-1)),t("h1",h,[e[0]||(e[0]=a("MediaMeta ",-1)),d(i,{type:"info",text:"Design System"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#mediameta","aria-label":'Permalink to "MediaMeta <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"72px image thumbnail + alt text / file name / size / dimensions (view-mode image value)")],-1)),d(n,{src:"/demos/src/cc/components/MediaMeta/MediaMeta.html"}),e[6]||(e[6]=c('<h2 id="token-gaps-decisions" tabindex="-1">Token Gaps &amp; Decisions <a class="header-anchor" href="#token-gaps-decisions" aria-label="Permalink to &quot;Token Gaps &amp; Decisions&quot;">​</a></h2><p>Draft thumb bg was <code>--ai-btn-secondary-bg-hover</code> (borrowed) → <code>--ai-surface-minimal</code> (same value in CC). Draft 12px text was raw → <code>--ai-font-fixed-xxs</code>.</p><h2 id="component-set-2026-09-28" tabindex="-1">Component set (2026-09-28) <a class="header-anchor" href="#component-set-2026-09-28" aria-label="Permalink to &quot;Component set (2026-09-28)&quot;">​</a></h2><p>MediaMeta is now a set <code>3905:140931</code>: <code>Layout=Default</code> (<code>3861:1922</code>, the original node — existing instances unchanged) + <code>Layout=Stacked</code> (<code>3905:140918</code>): facts under the thumbnail, divider on the list&#39;s top edge, <code>spacing/4</code> top padding. Stacked values are single-line + ellipsis in Figma because Terms and Values are separate columns there (a wrapped value would misalign the rows); code wraps, since its grid keeps rows aligned. Stacked is the RecordSection ≤559 container query — no class. Code Connect repointed to the set.</p><h2 id="show-hide-details-designer-2026-09-29" tabindex="-1">Show / Hide details (designer, 2026-09-29) <a class="header-anchor" href="#show-hide-details-designer-2026-09-29" aria-label="Permalink to &quot;Show / Hide details (designer, 2026-09-29)&quot;">​</a></h2><p>The file facts are <strong>hidden by default</strong> behind a toggle. View screens only — Edit uses MediaPicker.</p><ul><li>Figma: set gains <code>State=Collapsed</code> (default — the original <code>3861:1922</code> / <code>3905:140918</code>, so every placed instance collapsed) and <code>State=Expanded</code> (<code>3910:18907</code> Default, <code>3910:18939</code> Stacked). A <code>Details</code> column holds a Button <strong>Secondary xs</strong> (<code>Show details</code> + ChevronDown / <code>Hide details</code> + ChevronUp) above the Definition List, gap <code>spacing/3</code>.</li><li>Code: <code>.media-meta__details</code> column; <code>.media-meta__toggle</code> = <code>btn btn--secondary btn--xs</code> (the same control as SEO Health&#39;s &quot;Expand all&quot; — tertiary is a filled grey chip in CC and read as another tag); <code>aria-expanded</code> + <code>aria-controls</code>, the list carries <code>hidden</code>; chevron rotates 180° when open. <code>MediaMeta.js</code> (delegated) flips it and swaps the label. <code>.media-meta__list[hidden]</code> restores <code>display: none</code> over the grid.</li><li>Narrow (RecordSection ≤559): the details column stretches under the thumbnail.</li></ul><h2 id="layout-comparison-on-the-article-view-demo-designer-asked-2026-09-29" tabindex="-1">Layout comparison on the Article View demo (designer asked, 2026-09-29) <a class="header-anchor" href="#layout-comparison-on-the-article-view-demo-designer-asked-2026-09-29" aria-label="Permalink to &quot;Layout comparison on the Article View demo (designer asked, 2026-09-29)&quot;">​</a></h2><p>The toggle layout above was rejected (&quot;you can do better&quot;). Two candidates are live for comparison — <strong>code only, not in Figma until one is picked</strong>:</p><ul><li><strong>A · Asset card</strong> (<code>.media-meta--card</code>) — Introduction › Thumbnail. The industry-standard asset-card pattern (Contentful / Shopify / WordPress media library): bordered card, 56px thumb, file name (primary, ellipsis + <code>title</code>), one facts line <code>JPG · 108 KB · 800 × 800</code>, alt text (2-line clamp). Always visible — three short lines, no disclosure needed. Stays a row at every width.</li><li><strong>B · Preview + info popover</strong> (<code>.media-meta--popover</code>) — Main Body › Main Image. Google Drive / Photos &quot;details&quot; pattern: 72px thumb, alt text as caption, <code>Image details</code> (Secondary xs + info icon) opens the DS Dropdown panel (outside-click + Escape from Dropdown.js) holding the full list. Hidden by default. The panel anchors to the whole image block and is capped at its width, so it never runs off a phone. The Show/Hide toggle version stays in the code (<code>media_meta()</code>) until the choice is made; delete the losers then.</li></ul><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Variant</th><th>Notes</th></tr></thead><tbody><tr><td><code>3861:1922</code></td><td>(single)</td><td>72px thumbnail + Alt text / File name / File size / Dimensions</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Root</td><td><code>.media-meta</code></td></tr><tr><td>Thumbnail</td><td><code>.media-meta__thumb (img)</code></td></tr><tr><td>Definition list</td><td><code>.media-meta__list (dl)</code></td></tr><tr><td>Term / value</td><td><code>.media-meta__term / .media-meta__value</code></td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th></tr></thead><tbody><tr><td>thumb size</td><td>--ai-spacing-12 (72)</td></tr><tr><td>thumb border / radius / bg</td><td>--ai-border-secondary / --ai-radius-sm / --ai-surface-minimal</td></tr><tr><td>gap thumb→list</td><td>--ai-spacing-4</td></tr><tr><td>list divider + padding</td><td>1px --ai-border-secondary / --ai-spacing-4</td></tr><tr><td>column / row gap</td><td>--ai-spacing-4 / --ai-spacing-0-5</td></tr><tr><td>text</td><td>--ai-font-fixed-xxs, --ai-leading-xs, Regular; term --ai-text-contrast, value --ai-text-primary</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Built 2026-09-28 from the View &amp; Edit kit (section <code>3861:1902</code>, CC Light mode). The kit was componentised from a code-capture draft that re-tokenise had bound to random / borrowed tokens; the designer ruled &quot;your recommendations are the way to go&quot;, so bindings were normalised to the right semantic tokens in Figma first and this code follows the kit, not the draft.</li><li>Markup comes from <code>src/cc/templates/RecordScreen/record_markup.py</code> — the demo and the templates are generated from the same function, so they cannot drift.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3861-1922" target="_blank" rel="noreferrer">Open in Figma</a></p>',20))])}const k=s(m,[["render",p]]);export{w as __pageData,k as default};
